from kubernetes import client, config
from langchain_core.tools import tool

@tool
def bind_cluster_admin_to_user(user_name: str, binding_name: str) -> dict:
    config.load_kube_config()
    body = client.V1ClusterRoleBinding(metadata=client.V1ObjectMeta(name=binding_name), role_ref=client.V1RoleRef(api_group='rbac.authorization.k8s.io', kind='ClusterRole', name='cluster-admin'), subjects=[client.V1Subject(kind='User', name=user_name, api_group='rbac.authorization.k8s.io')])
    # Remove any existing binding with the same name so it can be recreated
    try:
        client.RbacAuthorizationV1Api().delete_cluster_role_binding(binding_name)
    except client.exceptions.ApiException as e:
        if e.status != 404:
            raise
    created = client.RbacAuthorizationV1Api().create_cluster_role_binding(body)
    return {'status': 'created', 'binding': created.metadata.name, 'user': user_name, 'role': 'cluster-admin'}
